import {dynamic} from '@github-ui/dynamic'
import {TransitionType} from '@github-ui/react-core/app-routing-types'
import {jsonRoute} from '@github-ui/react-core/json-route'
import {registerNavigatorApp} from '@github-ui/react-core/register-app'
import {relayEnvironmentWithMissingFieldHandlerForNode} from '@github-ui/relay-environment'
import {relayRoute} from '@github-ui/relay-route'
import {createElement} from 'react'
import {Fragment} from 'react/jsx-runtime'

import {App} from './App'
import RelaySandboxPageQuery$parameters from './routes/RelaySandboxPage/__generated__/RelaySandboxPageQuery$parameters'

const SandboxLayoutWithOutlet = dynamic(async () => {
  const module = await import('./SandboxLayout')
  return {default: module.SandboxLayoutWithOutlet}
})

const IndexPage = dynamic(async () => {
  const module = await import('./routes/Index')
  return {default: module.IndexPage}
})

const SSRErrorPage = dynamic(async () => {
  const module = await import('./routes/SSRError')
  return {default: module.SSRErrorPage}
})

const ShowPage = dynamic(async () => {
  const module = await import('./routes/Show')
  return {default: module.ShowPage}
})

const FilterPage = dynamic(async () => {
  const module = await import('./routes/Filter')
  return {default: module.FilterPage}
})

const CommentBoxPage = dynamic(async () => {
  const module = await import('./routes/CommentBox')
  return {default: module.CommentBoxPage}
})

const CssModules = dynamic(async () => {
  const module = await import('./routes/CssModules/CssModules')
  return {default: module.CssModules}
})

const StaticAsset = dynamic(async () => {
  const module = await import('./routes/StaticAsset')
  return {default: module.StaticAsset}
})

const UIDeploys = dynamic(async () => {
  const module = await import('./routes/UIDeploys')
  return {default: module.UIDeploys}
})

const GlobalNavigationPage = dynamic(async () => {
  const module = await import('./routes/GlobalNavigation')
  return {default: module.GlobalNavigationPage}
})

const RelaySandboxPage = dynamic(async () => {
  const module = await import('./routes/RelaySandboxPage/RelaySandboxPage')
  return {default: module.RelaySandboxPage}
})

registerNavigatorApp('react-sandbox', () => {
  const relayEnvironment = relayEnvironmentWithMissingFieldHandlerForNode()
  return {
    App,
    routes: [
      jsonRoute({
        path: '/_react_sandbox',
        Component: SandboxLayoutWithOutlet,
        transitionType: TransitionType.TRANSITION_WHILE_FETCHING,
        children: [
          {
            path: '/_react_sandbox',
            Component: IndexPage,
          },
          {
            path: '/_react_sandbox/ssr-error',
            Component: SSRErrorPage,
          },
          {
            path: '/_react_sandbox/:sandbox_id',
            Component: ShowPage,
          },
          {path: '/_react_sandbox/filter', Component: FilterPage},
          {path: '/_react_sandbox/comment-box', Component: CommentBoxPage},
          {path: '/_react_sandbox/css-modules', Component: CssModules},
          {path: '/_react_sandbox/static-asset', Component: StaticAsset},
          {path: '/_react_sandbox/ui-deploys', Component: UIDeploys},
          {path: '/_react_sandbox/global-navigation', Component: GlobalNavigationPage},
        ],
      }),
      relayRoute({
        path: '/_react_sandbox/relay',
        Component: RelaySandboxPage,
        resourceName: 'valid resource name',
        queryConfigs: {
          relaySandboxPage: {
            concreteRequest: RelaySandboxPageQuery$parameters,
          },
        },
        title: 'title',
        relayEnvironment,
        // eslint-disable-next-line @github-ui/github-monorepo/no-react-create-element -- Convert to JSX. This may require using a tsx file.
        fallback: createElement(Fragment),
      }),
    ],
  }
})
